<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$staffRoles=['admin','director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher','hr','storekeeper','bursar','driver'];if(!in_array($role,['parent','pupil',...$staffRoles],true)){http_response_code(403);exit('Your role cannot access announcements.');}$db=db();$groups=[];
if($role==='parent'){$selected=(int)($_GET['pupil_id']??0);$sql="SELECT p.id pupil_id,p.first_name,p.last_name,s.id school_id,s.name school_name FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id JOIN schools s ON s.id=g.school_id WHERE g.guardian_user_id=? AND p.status='active'";$params=[$uid];if($selected){$sql.=' AND p.id=?';$params[]=$selected;}$sql.=' ORDER BY s.name,p.last_name,p.first_name';$q=$db->prepare($sql);$q->execute($params);$children=$q->fetchAll();if($selected&&!$children){http_response_code(404);exit('Linked child not found.');}foreach($children as $child){$q=$db->prepare("SELECT title,body,published_at,expires_at FROM school_announcements WHERE school_id=? AND status='published' AND published_at<=CURRENT_TIMESTAMP AND (expires_at IS NULL OR expires_at>=CURRENT_DATE) AND audience IN ('all','parents') ORDER BY published_at DESC LIMIT 20");$q->execute([$child['school_id']]);$groups[]=['name'=>trim($child['first_name'].' '.$child['last_name']),'school'=>$child['school_name'],'items'=>$q->fetchAll()];}}
elseif($role==='pupil'){$q=$db->prepare("SELECT p.school_id,s.name school_name FROM pupil_accounts a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id JOIN schools s ON s.id=p.school_id WHERE a.user_id=? AND a.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$pupil=$q->fetch();if(!$pupil){http_response_code(403);exit('No active pupil account is linked.');}$q=$db->prepare("SELECT title,body,published_at,expires_at FROM school_announcements WHERE school_id=? AND status='published' AND published_at<=CURRENT_TIMESTAMP AND (expires_at IS NULL OR expires_at>=CURRENT_DATE) AND audience IN ('all','pupils') ORDER BY published_at DESC LIMIT 20");$q->execute([$pupil['school_id']]);$groups[]=['name'=>'Your class','school'=>$pupil['school_name'],'items'=>$q->fetchAll()];}

else{$q=$db->prepare('SELECT s.id school_id,s.name school_name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);foreach($q->fetchAll() as $schoolRow){$q=$db->prepare("SELECT title,body,published_at,expires_at FROM school_announcements WHERE school_id=? AND status='published' AND published_at<=CURRENT_TIMESTAMP AND (expires_at IS NULL OR expires_at>=CURRENT_DATE) AND audience IN ('all','staff') ORDER BY published_at DESC LIMIT 20");$q->execute([$schoolRow['school_id']]);$groups[]=['name'=>'Staff notice board','school'=>$schoolRow['school_name'],'items'=>$q->fetchAll()];}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School announcements · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Portal <span>/</span> Announcements</div><div class="top-actions"><span class="role-chip"><?=e($role==='parent'?'Parent / Guardian':($role==='pupil'?'Pupil / Learner':'School staff'))?></span></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SCHOOL NOTICES</div><h1>Announcements</h1><p class="muted">Published notices visible to your linked school and account audience.</p></div></section><?php if(!$groups):?><div class="empty-state"><h2>No linked pupils</h2><p>Ask your school to link this account to a pupil.</p></div><?php endif;?><?php foreach($groups as $group):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow"><?=e($group['school'])?></div><h2><?=e($group['name'])?></h2></div></div><?php if($group['items']):?><div class="question-list"><?php foreach($group['items'] as $a):?><article class="question-card"><h3><?=e($a['title'])?></h3><div><?=nl2br(e($a['body']))?></div><p class="muted">Published <?=e(date('j M Y',strtotime($a['published_at'])))?><?php if($a['expires_at']):?> · Expires <?=e(date('j M Y',strtotime($a['expires_at'])))?><?php endif;?></p></article><?php endforeach;?></div><?php else:?><p class="muted">No published announcements for this audience.</p><?php endif;?></section><?php endforeach;?><footer class="page-footer">ShuleLite · School communication</footer></div></main></div></body></html>
